def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    if not alive:
        base = 0.35 * DAILY_SALARY
        if hp <= 2 or no_water >= 1:
            base = 0.75 * DAILY_SALARY
        return max(0, min(budget, base))

    prev_bids = []
    stressed_opp_bid = None
    max_prev = 0
    min_prev = None
    error_count = 0
    high_need_count = 0

    for opp in alive:
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            high_need_count += 1
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('error'):
            error_count += 1
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)
            if bid > max_prev:
                max_prev = bid
            if min_prev is None or bid < min_prev:
                min_prev = bid
            if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
                if stressed_opp_bid is None or bid > stressed_opp_bid:
                    stressed_opp_bid = bid

    scarcity = 1.0 - ((supply - 15.0) / 10.0)
    if scarcity < 0:
        scarcity = 0
    if scarcity > 1:
        scarcity = 1

    urgency = 0.0
    if hp <= 2:
        urgency += 0.55
    elif hp <= 4:
        urgency += 0.3
    if no_water >= 1:
        urgency += 0.25
    if no_water >= 2:
        urgency += 0.2

    pressure = 0.25 + 0.35 * scarcity + urgency
    if high_need_count >= 2:
        pressure += 0.08
    if error_count > 0:
        pressure -= 0.05

    if pressure < 0.15:
        pressure = 0.15
    if pressure > 1.15:
        pressure = 1.15

    bid = DAILY_SALARY * pressure

    if prev_bids:
        if hp <= 2 or no_water >= 1:
            target = max_prev + 1.5
            if stressed_opp_bid is not None:
                target = max(target, stressed_opp_bid + 1.5)
            bid = max(bid, target)
        else:
            if max_prev >= 0.9 * DAILY_SALARY and scarcity > 0.5:
                bid = min(bid, 0.32 * DAILY_SALARY)
            elif min_prev is not None and scarcity < 0.35:
                bid = max(bid, min_prev + 0.75)
            else:
                bid = max(bid, max_prev * 0.78)
    else:
        if hp <= 2 or no_water >= 1:
            bid = max(bid, 0.82 * DAILY_SALARY)
        elif scarcity < 0.25:
            bid = min(bid, 0.42 * DAILY_SALARY)

    remaining_days = 10 - day
    reserve = 0
    if remaining_days > 0:
        reserve = remaining_days * 0.18 * DAILY_SALARY
    affordable = budget - reserve
    if affordable < 0:
        affordable = budget * 0.5

    if hp <= 2 or no_water >= 1:
        affordable = budget

    bid = min(bid, affordable, budget)
    if bid < 0:
        bid = 0

    if budget < 0.35 * DAILY_SALARY and not (hp <= 2 or no_water >= 1):
        bid = min(bid, budget)

    return max(0, bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = day_context['day']

    # Alive opponents
    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # Base affordability
    budget = float(my_status.get('budget', 0.0))
    hp = float(my_status.get('hp', 0.0))

    # If no opponents, just bid enough to meet requirement if possible
    if not alive_opps:
        target = min(budget, DAILY_SALARY * 0.45)
        return max(0.0, float(target))

    # Read yesterday bids from previous_trace (immediate reaction only)
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Determine pressure from opponent yesterday bids
    pressure = 0.0
    if prev_bids:
        pressure = max(prev_bids)

    # Heuristic: if someone already overpaid aggressively, raise slightly to contest
    # Otherwise keep moderate to preserve budget for later days.
    if pressure >= DAILY_SALARY * 0.85:
        # If we're low HP, bid more to prevent future no-water days
        if hp <= 2.0:
            bid = DAILY_SALARY * 0.75
        else:
            bid = DAILY_SALARY * 0.55
    else:
        # Scale with supply: lower supply -> bid higher to secure water
        # supply in [15,25], requirement 9 => 1 unit likely; bid to contest but not max out
        if supply <= 17.0:
            bid = DAILY_SALARY * 0.60
        elif supply <= 20.0:
            bid = DAILY_SALARY * 0.50
        else:
            bid = DAILY_SALARY * 0.42

    # Ensure bid does not exceed budget
    bid = min(float(bid), budget)

    # If budget is extremely low, bid what we can
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)
    total_active_players = num_alive_opponents + 1 # Include myself

    # --- Survival Bids ---
    # If HP is critical (2 or less) or I missed water yesterday, bid very high to survive.
    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        return min(my_status['budget'], DAILY_SALARY * 0.98) # Very aggressive bid

    # --- No Opponents / Ample Supply ---
    if not alive_opponents:
        # No competition, bid low to conserve budget while securing water.
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    supply = day_context['supply']
    # Calculate how many players can get their full water requirement.
    num_possible_winners = int(supply // WATER_REQ)

    # If there's enough water for everyone to get their requirement, bid moderately.
    if num_possible_winners >= total_active_players:
        # Still bid moderately to ensure a win, but don't overspend unnecessarily.
        return min(my_status['budget'], DAILY_SALARY * 0.5)

    # --- Competitive Bidding based on Opponent's Previous Actions ---
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.6 # Default moderate competitive bid

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If opponents were very aggressive yesterday (bid high).
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # If I have decent HP buffer, try to outbid them slightly.
            if my_status['hp'] > 4:
                base_bid = max(base_bid, highest_prev_bid + 2) 
            else:
                # Less buffer, need water more, so bid more aggressively.
                base_bid = max(base_bid, highest_prev_bid + 5) 
        # If opponents were conservative yesterday (bid low).
        elif highest_prev_bid < DAILY_SALARY * 0.5:
            # Even if opponents were conservative, if supply is tight, maintain a competitive bid.
            if num_possible_winners < total_active_players:
                base_bid = max(base_bid, DAILY_SALARY * 0.6) 
            else:
                base_bid = max(base_bid, DAILY_SALARY * 0.4) # More conservative if ample water
        else:
            # Moderate previous bids, react by slightly exceeding the highest previous bid to win.
            base_bid = max(base_bid, highest_prev_bid + 1)

    # If no previous bids (e.g., Day 1) and supply is tight, use a solid competitive bid.
    if not yesterday_bids and num_possible_winners < total_active_players:
        base_bid = DAILY_SALARY * 0.7 # Solid competitive bid for initial competitive scenarios

    # Ensure the bid does not exceed the current budget.
    return min(my_status['budget'], base_bid)
